import { gsap } from 'gsap';
import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { uv, vec3, vec4, mix, smoothstep, time, uniform, texture, float } from 'three/tsl';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const group = new THREE.Group();

  const timelines = [];
  const meshes = [];

  // Parse text content with bridging idiom
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  let captionText = '';
  let heroText = '';
  let subheadText = '';

  for (const item of items) {
    if (item.role === 'caption' || (item.typography?.fontSize === 18)) {
      captionText = item.text;
    } else if (item.role === 'hero' || (item.typography?.fontSize === 124)) {
      heroText = item.text;
    } else if (item.role === 'subhead' || (item.typography?.fontSize === 40)) {
      subheadText = item.text;
    }
  }

  // Color palette
  const colors = {
