  };

  // === BACKDROP PLANE ===
  const backdropGeom = new THREE.PlaneGeometry(7, 5.5);
  const backdropMat = new MeshBasicNodeMaterial({
    side: THREE.FrontSide,
    transparent: true
  });

  // Gradient from #0b0b10 (top) to #13131a (bottom) with mono grain
  const gradientNode = mix(
    vec3(0.0431, 0.0431, 0.0627), // #0b0b10
    vec3(0.0745, 0.0745, 0.1020)  // #13131a
  );

  // Add subtle mono grain texture
  const grainUV = uv();
  const grain = smoothstep(0.3, 0.7, 
    mix(grainUV.x, grainUV.y, 0.5)
  ).mul(0.015);

  backdropMat.colorNode = mix(
    gradientNode,
    vec3(0.5),
    grain
  );

