      fontSize: 18,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 2.16 // 0.12 * 18
    });
    captionObj.position.y = 1.15;
    captionObj.position.z = 0;
    group.add(captionObj);
  }

  // === HERO HEADLINE (kinetic, per-word depth parallax) ===
  const heroGroup = new THREE.Group();
  heroGroup.position.y = 0.4;
  heroGroup.position.z = 0;

  if (heroText) {
    const words = heroText.split(/\s+/);
    const wordGroups = [];
    let xOffset = 0;

    const wordZOffsets = [0.12, 0.0, -0.12];
    const wordZMap = {};
    words.forEach((word, idx) => {
      wordZMap[word + idx] = wordZOffsets[idx % wordZOffsets.length];
    });

    for (let widx = 0; widx < words.length; widx++) {
      const word = words[widx];
      const wordGroup = new THREE.Group();

      const wordObj = ctx.fontAtlas.createText(word, {
        fontSize: 124,
        color: colors.paper,
        align: 'left',
        letterSpacingPx: -1.24 // -0.01 * 124
      });

      const zDepth = wordZMap[word + widx] || 0.0;
      wordObj.position.z = zDepth;

      // Stagger glyphs left-to-right across word
      const glyphCount = word.length;
      for (let gidx = 0; gidx < wordObj.children.length; gidx++) {
        const glyph = wordObj.children[gidx];

        // Rise-in animation per glyph: y +0.35 -> 0, opacity 0 -> 1
        // 700ms total, 60ms stagger, cubic-bezier(0.215, 0.61, 0.355, 1)
        const totalGlyphIndex = gidx;
        const delay = totalGlyphIndex * 0.06;

        glyph.position.y = 0.35;
        if (glyph.material) {
