            { opacity: 1, duration: 0.7, ease: 'cubic-bezier(0.215, 0.61, 0.355, 1)' },
            0
          );
        }

        // Start each glyph animation on load
        glyphTL.play();
        glyphTL.seek(delay);
        timelines.push(glyphTL);
      }

      wordGroup.add(wordObj);
      heroGroup.add(wordGroup);
      wordGroups.push(wordGroup);
    }

    group.add(heroGroup);

    // Weighted settle on hero group after all glyphs have landed
    // Triggered when last glyph completes (700ms + max stagger)
    const lastGlyphCompleteTime = (words.reduce((sum, w) => sum + w.length, 0) - 1) * 0.06 + 0.7;

    const settleTL = gsap.timeline({ paused: true });
    settleTL.to(heroGroup.scale,
