  underline.scale.x = 0;
  underline.geometry.translate(-1.3, 0, 0); // Anchor to left
  group.add(underline);

  // Underline scales in 120ms after last glyph lands
  const lastGlyphCompleteTime = heroText 
    ? (heroText.length - 1) * 0.06 + 0.7 
    : 0;

  const underlineTL = gsap.timeline({ paused: true });
  underlineTL.to(underline.scale,
    {
      x: 1,
      duration: 0.5,
