  timelines.push(underlineTL);

  // === SUBHEAD (fade up at y=-0.65) ===
  if (subheadText) {
    const subheadObj = ctx.fontAtlas.createText(subheadText, {
      fontSize: 40,
      color: colors.paper,
      align: 'center',
      letterSpacingPx: 0.8 // 0.02 * 40
    });

    subheadObj.position.y = -0.65;
    subheadObj.position.z = 0;
    subheadObj.position.y += 0.2; // Start offset for fade-up

    // Fade up: opacity 0->1, y +0.2->0, 500ms
    const subheadTL = gsap.timeline({ paused: true });
    subheadTL.to(subheadObj.position,
      {
        y: -0.65,
        duration: 0.5,
        ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)'
      },
      0
    );

    // Set initial opacity to 0 on all children
    subheadObj.traverse((child) => {
      if (child.material && !child.material.emissive) {
        child.material.transparent = true;
        child.material.opacity = 0;
      }
    });

    subheadObj.traverse((child) => {
      if (child.material && child.material.opacity !== undefined) {
        subheadTL.to(child.material,
          { opacity: 1, duration: 0.5, ease: 'cubic-bezier(0.25, 0.46, 0.45, 0.94)' },
          0
        );
      }
    });

    const subheadStartTime = lastGlyphCompleteTime;
    subheadTL.play();
    subheadTL.seek(subheadStartTime);
    timelines.push(subheadTL);

    group.add(subheadObj);
  }

  // === CINEMATIC PRIMITIVE: kinetic-text ===
  // Already applied manually above with per-glyph stagger and weighted settle
  // The primitive call is optional if manual implementation covers the spec
  if (ctx.primitives && ctx.primitives['kinetic-text']) {
    try {
      const primitiveResult = ctx.primitives['kinetic-text'](group, {
        staggerMs: 60,
        riseUnits: 0.35
      });
      if (primitiveResult && primitiveResult.cleanup) {
        timelines.push({ cleanup: primitiveResult.cleanup });
      }
    } catch (e) {
      // Primitive not available; manual implementation covers it
    }
  }

  // === CLEANUP ===
  group.userData.cleanup = function() {
    timelines.forEach(tl => {
      if (tl.kill) tl.kill();
      if (tl.cleanup) tl.cleanup();
    });
    meshes.forEach(m => {
      if (m.geometry) m.geometry.dispose();
      if (m.material) {
        if (Array.isArray(m.material)) {
          m.material.forEach(mat => mat.dispose());
        } else {
          m.material.dispose();
        }
      }
    });
    group.traverse((child) => {
      if (child.geometry) child.geometry.dispose();
      if (child.material) {
        if (Array.isArray(child.material)) {
          child.material.forEach(mat => mat.dispose());
        } else {
          child.material.dispose();
        }
      }
    });
  };

  return group;
}
